buggy.narrow_float_special_values:
import warnings
import numpy as np
import pandas as pd
from pandas.core.dtypes.cast import maybe_downcast_numeric

def _count_runtime_warnings(fn):
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        try:
            fn()
        except Exception:
            pass
    return float(sum(1 for w in caught if issubclass(w.category, RuntimeWarning)))

def _downcast_float16():
    return maybe_downcast_numeric(np.array([1.0, 2.0], dtype="float16"), np.dtype("int64"))

def _setitem_float16():
    ser = pd.Series([1, 2], dtype="int64")
    ser.loc[2] = np.float16(3.0)

def _convert_dtypes_float16():
    return pd.Series([1.0, 2.0], dtype="float16").convert_dtypes()

def _kind(values):
    res = pd.Series(values).convert_dtypes()
    return 1.0 if str(res.dtype) == "Int64" else 0.0

probe("downcast_float16_runtime_warnings", _count_runtime_warnings(_downcast_float16))
probe("setitem_float16_runtime_warnings", _count_runtime_warnings(_setitem_float16))
probe("convert_dtypes_float16_runtime_warnings", _count_runtime_warnings(_convert_dtypes_float16))
probe("kind_two_pow_63", _kind([2.0 ** 63]))
probe("kind_1e30", _kind([1e30]))
probe("kind_inf", _kind([np.inf]))
probe("kind_intmax_plus_one", _kind([float(np.iinfo(np.int64).max) + 1.0]))
probe("kind_in_range_1_2", _kind([1.0, 2.0]))

